let readingStep=0;
try{const saved=Number(localStorage.getItem('posh-reading-size'));if(Number.isInteger(saved)&&saved>=0&&saved<=2)readingStep=saved;}catch{}
function applyReadingSize(){
 document.documentElement.style.setProperty('--reading-scale',String(1+readingStep*.1));
 document.getElementById('reading-size').textContent=(100+readingStep*10)+'%';
 document.querySelector('[data-reading="smaller"]').disabled=readingStep===0;
 document.querySelector('[data-reading="larger"]').disabled=readingStep===2;
}
applyReadingSize();
document.addEventListener('click',e=>{const settings=document.querySelector('.reading-settings');if(settings?.open&&!settings.contains(e.target))settings.open=false;});
document.addEventListener('keydown',e=>{const settings=document.querySelector('.reading-settings');if(e.key==='Escape'&&settings?.open){settings.open=false;settings.querySelector('summary').focus();}});
window.addEventListener('hashchange',()=>{const settings=document.querySelector('.reading-settings');if(settings)settings.open=false;});
document.addEventListener('click',e=>{
 const button=e.target.closest('[data-reading]');if(!button)return;
 readingStep=button.dataset.reading==='reset'?0:Math.max(0,Math.min(2,readingStep+(button.dataset.reading==='larger'?1:-1)));
 applyReadingSize();try{localStorage.setItem('posh-reading-size',String(readingStep));}catch{}
});
