function bindHomeWalkthrough(){
 const form=document.getElementById('home-walkthrough-form');
 const status=document.getElementById('home-walkthrough-status');
 const button=form.querySelector('button');
 const email=document.getElementById('home-walkthrough-email');
 const copy=document.getElementById('home-walkthrough-copy');
 const copyStatus=document.getElementById('home-walkthrough-copy-status');
 copy.hidden=false;
 copy.addEventListener('click',async()=>{
   try{
     await navigator.clipboard.writeText(email.textContent);
     copyStatus.textContent='Email address copied.';
   }catch{
     const selection=window.getSelection();
     if(selection){
       const range=document.createRange();
       range.selectNodeContents(email);
       selection.removeAllRanges();
       selection.addRange(range);
     }
     copyStatus.textContent='Copy the email address above into your email app.';
   }
 });
 form.hidden=false;
 fetch('/api/enquiries/config',{signal:AbortSignal.timeout(8000)}).then(r=>r.ok?r.json():{}).then(r=>{button.disabled=r.enabled!==true;if(button.disabled)status.textContent='Online requests are unavailable. Email the team below.';}).catch(()=>{status.textContent='Online requests are unavailable. Email the team below.';});
 form.addEventListener('submit',async event=>{
   event.preventDefault();if(button.disabled)return;button.disabled=true;
   const data=Object.fromEntries(new FormData(form));
   const payload={...data,contact_name:'Walkthrough requester',plan:'unsure',need:'Core inquiry workflow and record organisation',consent:data.consent==='on'};
   status.textContent='Saving your request…';
   try{
     const response=await fetch('/api/enquiries',{method:'POST',headers:{'Content-Type':'application/json',...(window.NavigatorAnalytics?.enquiryHeaders()||{})},body:JSON.stringify(payload),signal:AbortSignal.timeout(20000)});
     const result=await response.json();if(!response.ok||result.status!=='received')throw Error(result.error||'Request could not be confirmed.');
     status.textContent='Request received. Reference '+result.receipt+'. The team will contact you about your walkthrough.';
     form.reset();form.querySelectorAll('input,select').forEach(field=>field.disabled=true);
   }catch(error){button.disabled=false;status.textContent=error.message||'Please contact the team before repeating your request.';}
 });
}
