function whyProcedureMatters(){return `<section class="section review-readiness" aria-labelledby="review-readiness-title"><div class="wrap"><div class="home-section-heading"><div><span class="eyebrow dark">BETTER PREPARED FOR SCRUTINY, REVIEW & APPEAL</span><h2 id="review-readiness-title">Build the record now.<br/>Be ready to explain it later.</h2></div><p>An appeal is a lawful safeguard. Avoidable gaps in notice, participation or reasoning can make a decision harder to defend. Our planned workflow is designed to help your Committee spot and document those issues before the next step—not reconstruct the process after a challenge.</p></div><div class="review-risk-grid"><article><span class="risk-kind">FAIR HEARING · SUPREME COURT</span><h3>Speed cannot replace a fair opportunity.</h3><p>In <em>Aureliano Fernandes</em>, the Court found that rushed proceedings damaged fairness and remitted the matter. A balanced opportunity for both sides mattered.</p><p class="risk-support"><strong>Planned support:</strong> organise notices, hearing dates, responses and procedural directions.</p><details><summary>Judgment and limits</summary><p><strong>Aureliano Fernandes v. State of Goa</strong>, 12 May 2023, paragraphs 69–73. The case arose in a service-inquiry framework. It does not make every procedural defect an automatic ground to invalidate an inquiry.</p><a href="#faq/case-c05">Read the judgment note and source →</a></details></article><article><span class="risk-kind">DEFENCE & REPORT ACCESS · DELHI HIGH COURT</span><h3>A missing opportunity can mean doing the work again.</h3><p>In <em>Union of India v. Naresh</em>, denial of a fair defence opportunity and non-supply of the report supported a fresh inquiry.</p><p class="risk-support"><strong>Planned support:</strong> track relevant records, responses, report preparation and readiness checks.</p><details><summary>Judgment and limits</summary><p>Delhi High Court, 7 January 2026, paragraphs 42–47. The fresh-inquiry directions were case-specific; reinstatement was restricted during that inquiry. The decision did not establish harassment on the merits.</p><a href="#faq/case-c33">Read the judgment note and source →</a></details></article><article><span class="risk-kind">ATTENDANCE & ABSENCE · STATUTORY CHECKPOINT</span><h3>Attendance is more than a calendar entry.</h3><p>Where the Central Rules apply, minimum participation includes three members with the Presiding Officer or Chairperson. Termination or an ex parte decision requires separate absence and advance-notice safeguards.</p><p class="risk-support"><strong>Planned support:</strong> hearing attendance and participation records, with human verification of the applicable requirements.</p><div class="risk-rules">${window.NavigatorLegal.referenceHTML('Central Rule 7(5)')} · ${window.NavigatorLegal.referenceHTML('Central Rule 7(7)')}</div><p class="risk-limit">Application-user allowances do not replace Committee membership or hearing quorum.</p></article><article><span class="risk-kind">COMPETENT FORUM · DELHI HIGH COURT</span><h3>The right record also needs the right authority.</h3><p>In <em>the Delhi High Court Local Committee judgment</em>, the Secretary was treated as the employer under the governing framework; the IC report issued without jurisdiction was set aside.</p><p class="risk-support"><strong>Planned support:</strong> authority and forum checkpoints for competent Committee determination.</p><details><summary>Judgment and limits</summary><p>Delhi High Court, 28 August 2025, paragraphs 98 and 106–114. The decision turned on the institution’s governance and facts. A Secretary, Director or CEO title alone does not decide the forum.</p><a href="#faq/case-c22">Read the judgment note and source →</a></details></article></div><div class="review-readiness-next"><div><strong>The best time to check the process is before the next hearing.</strong><p>A later report cannot replace an opportunity that was never given. Explore Professional’s planned checks before inquiry, before report and after report. No plan guarantees a court outcome; fair-process safeguards remain part of every paid tier.</p></div><a class="btn btn-gold" href="#enquire?plan=professional">See the three readiness reviews →</a></div></div></section>`;}

function socialProof(){return `<section class="section social-proof" aria-labelledby="proof-title"><div class="wrap proof-layout"><div><span class="eyebrow dark">PRACTICAL EXPERIENCE · PUBLICLY DOCUMENTED</span><h2 id="proof-title">Practical POSH experience.<br/>Feedback you can verify.</h2><p>POSH Legal Navigator is by The Cosmic Energizers, founded by Ankur Agrawal. The published feedback below documents his POSH training work. See the planned workflow for your own Committee, then decide whether the scope fits.</p><a class="btn btn-dark" href="#enquire?plan=professional">Show me how this fits my Committee →</a></div><figure class="institution-feedback"><span class="proof-label">PUBLISHED INSTITUTIONAL FEEDBACK</span><blockquote>“valuable guidance, clear explanations, and practical insights, which made the session informative and engaging for all staff members.”</blockquote><figcaption><strong>Radha Lal Geeta Vidya Mandir Sr. Sec. School</strong><span>POSH training session · Ambala · 31 January 2026</span></figcaption><a class="text-link" href="https://rlgvm.in/category/uncategorized/page/2/" target="_blank" rel="noopener noreferrer">Read the school’s published report ↗</a><p class="proof-context">Feedback concerns Ankur Agrawal’s POSH training, not use or endorsement of the planned software.</p></figure></div></section>`;}

function professionalPreview(){return `<section class="section product-preview-section" id="product-preview" aria-labelledby="product-preview-title"><div class="wrap"><div class="home-section-heading"><div><span class="eyebrow dark">SEE THE IDEA BEFORE YOU CHOOSE</span><h2 id="product-preview-title">A clearer record.<br/>A more useful working view.</h2></div><p>A fictional interface sample of the planned professional workspace. Explore the difference between organising a record, planning questions and preparing a report.</p></div><div class="product-concept"><div class="concept-top"><div><span class="concept-mark">N</span><strong>Committee workspace</strong></div><span class="concept-label">FICTIONAL DESIGN SAMPLE · NOT LIVE SOFTWARE</span></div><div class="concept-body"><div class="concept-tabs" role="tablist" aria-label="Explore the planned workspace"><button type="button" id="concept-tab-record" role="tab" aria-controls="concept-record" aria-selected="true" data-concept-tab="record">01 · Connected record</button><button type="button" id="concept-tab-questions" role="tab" aria-controls="concept-questions" aria-selected="false" tabindex="-1" data-concept-tab="questions">02 · Question planning</button><button type="button" id="concept-tab-report" role="tab" aria-controls="concept-report" aria-selected="false" tabindex="-1" data-concept-tab="report">03 · Report structure</button><p>Illustrations use codes only. No real names, case data or uploads.</p></div><div class="concept-content"><section id="concept-record" role="tabpanel" tabindex="0" aria-labelledby="concept-tab-record"><span class="concept-tier">ESSENTIAL: BASIC · PROFESSIONAL+: FULL MATRIX</span><h3>Keep both sides of the record in view.</h3><p>Illustration: accounts of a fictional meeting have different timings. The view keeps the difference visible for Committee verification.</p><div class="concept-table-wrap" role="region" tabindex="0" aria-label="Fictional record table; scroll horizontally if needed"><table class="concept-table"><caption>Illustrative record only · no finding or credibility score</caption><thead><tr><th scope="col">Reference</th><th scope="col">Record</th><th scope="col">Review point</th></tr></thead><tbody><tr><th scope="row">W-01</th><td>Witness account places the meeting in the afternoon.</td><td>Clarify what was personally observed.</td></tr><tr><th scope="row">E-01</th><td>Calendar entry shows a different time.</td><td>Check the entry and seek an explanation.</td></tr></tbody></table></div><div class="concept-human">Committee review pending · No conclusion generated</div></section><section id="concept-questions" role="tabpanel" tabindex="0" aria-labelledby="concept-tab-questions" hidden><span class="concept-tier">PROFESSIONAL: EVIDENCE-LINKED · ADVANCED: ADAPTIVE</span><h3>Questions that clarify the record.</h3><p>Illustrative planning cards show how a reference can sit beside a neutral clarification prompt.</p><div class="concept-question"><span>W-01 · PERSONAL OBSERVATION</span><strong>What did you personally observe at the meeting?</strong><small>Purpose: separate direct observation from information received later.</small></div><div class="concept-question"><span>E-01 · TIMING DIFFERENCE</span><strong>What explains the difference between these two times?</strong><small>Purpose: seek clarification without assuming either account is correct.</small></div><div class="concept-human">Illustrative prompts · Human selection and review required</div></section><section id="concept-report" role="tabpanel" tabindex="0" aria-labelledby="concept-tab-report" hidden><span class="concept-tier">PROFESSIONAL+: CURRENT LEGAL REPORT BUILDER</span><h3>Structure that makes reasoning easier to follow.</h3><p>A partial outline illustrates the planned report organisation. This is not a completed inquiry report or a downloadable case template.</p><ol class="concept-outline"><li><strong>Authority & applicable procedure</strong><span>Record the basis for the proceeding.</span></li><li><strong>Issues & material considered</strong><span>Connect the relevant records and responses.</span></li><li><strong>Committee reasoning</strong><span>Human evaluation and conclusions remain required.</span></li><li><strong>Review & approval</strong><span>Draft remains pending authorised review.</span></li></ol><div class="concept-human">No automated guilt, credibility or legal-outcome decision</div></section></div></div></div><div class="preview-next"><p>Want to see how this could fit your Committee’s work?</p><a class="btn btn-dark" href="#enquire?plan=professional">Request a personalised demonstration →</a><a class="text-link" href="#pricing">Compare planned capabilities</a></div></div></section>`;}
function questionClinic(){const examples=[{title:'A question that supplies the conclusion',bad:'We know the respondent threatened you. Confirm that this is what happened.',risk:'The Committee appears to adopt a disputed allegation and lead the witness toward its preferred answer.',better:'What did you personally see or hear? Please describe the words, actions and context, and distinguish them from anything you were told by someone else.',support:'Essential: neutral role-based prompts. Professional: allegation-specific, evidence-linked question planning for Committee consideration.',basis:'Neutrality principle: Ram Avtar Singh, paragraph 32; this wording is our illustration, not a question reproduced from the judgment.'},{title:'A question that presumes guilt',bad:'Why are you refusing to admit the misconduct?',risk:'It treats the disputed misconduct as established before the response and evidence have been considered.',better:'What is your response to this specific allegation? Which parts do you accept or dispute, and what material would you like the Committee to consider?',support:'Professional: a full matrix of supporting and contrary material, linked to the allegation and draft reasons.',basis:'Independent adjudication principle: Ram Avtar Singh, paragraph 32. Firm clarification is permitted; the issue is prejudgment and the conduct of the inquiry as a whole.'},{title:'A question asked without a fair response opportunity',bad:'We will rely on a message you have not seen. Why should we not find against you?',risk:'The person may be unable to address the actual material being relied on. Fairness depends on applicable procedure and necessary protective arrangements.',better:'After providing the relevant material through the applicable procedure: what is your response to this message, its context and the inference proposed?',support:'Essential: notice, reply and hearing records. Professional: evidence references and readiness reviews to help the Committee identify gaps.',basis:'Fair-defence principle: Union of India v. Naresh, paragraphs 42–45. It does not establish an unrestricted right to direct confrontation or disclosure without safeguards.'}];const stages=[['01','Complaint submission','An unclear factual starting point can leave later questions unfocused.','Essential: complaint and limitation checkpoints for Committee review.'],['02','Forum, constitution & confidentiality','The correct authority and an impartial Committee come before the merits.','Essential: authority, conflict and confidentiality checkpoints.'],['03','Voluntary conciliation','Pressure to settle can undermine a genuinely voluntary choice.','Essential: a separate conciliation pathway and procedural records.'],['04','Complaint copy & reply','A response needs the relevant particulars and a fair opportunity to address them.','Essential: notice, delivery, reply and deadline tracking.'],['05','Inquiry & hearings','Attendance, participation and directions need a usable record.','Essential: hearing diary, daily orders and attendance safeguards.'],['06','Witnesses & evidence','Leading assumptions and disconnected exhibits can obscure the actual evidence.','Professional: evidence-linked question planning and full allegation matrix; Advanced adds adaptive tools.'],['07','Findings & report','The conclusion should be traceable to the material and the reasons.','Essential: a basic template. Professional: current case-adaptive legal report builder, source references and readiness checks.'],['08','Action on recommendations','The record should show what was communicated and acted on.','Essential: core deadline tracking and standard procedural records/exports.'],['09','Appeal & post-report rights','A review needs the relevant record; appeal rights remain available.','Professional: report consistency and post-report readiness review. Advanced adds remand and recovery support.']];return `<section class="section question-clinic" aria-labelledby="question-clinic-title"><div class="wrap"><div class="home-section-heading"><div><span class="eyebrow dark">SEE WHY THE DETAIL MATTERS</span><h2 id="question-clinic-title">The question you ask.<br/>The fairness it reveals.</h2></div><p>Good intentions are not enough if the hearing record suggests a closed mind or a missing opportunity. Compare these fictional examples with a more neutral approach—and see where the planned tools fit.</p></div><details class="question-court-context"><summary>What the courts actually found · Read the sources</summary><p><em>Ram Avtar Singh v. Chairman &amp; Managing Director, Central Warehousing Corporation</em>, Delhi High Court, 7 August 2023, paragraph 32: the inquiry officer acted as presenting officer, compromising impartial adjudication. The disciplinary orders were set aside for multiple defects; this was a service inquiry, not a POSH decision. <a target="_blank" rel="noreferrer" href="https://dhccaseinfo.nic.in/jupload/dhc/JIS/judgement/17-08-2023/JIS07082023CW44742017_183956.pdf#page=22">Read the court’s judgment ↗</a></p><p><em>Union of India v. Naresh</em>, Delhi High Court, 7 January 2026, paragraphs 42–45: denial of fair defence and non-supply of the report supported a fresh inquiry. <a href="#faq/case-c33">Read the case and limits →</a></p><p><strong>A fresh inquiry is not an automatic consequence of one poorly worded question.</strong> Courts assess the applicable procedure, the record, bias or unfairness and the remedy required on the facts.</p></details><div class="question-examples">${examples.map((e,i)=>`<details class="question-example" ${i===0?'open':''}><summary><span>0${i+1}</span> ${h(e.title)}</summary><div class="question-example-body"><div class="question-pair"><div class="question-risk"><span>ILLUSTRATIVE RISKY WORDING</span><p>“${h(e.bad)}”</p><p>${h(e.risk)}</p></div><div class="question-neutral"><span>A MORE NEUTRAL APPROACH</span><p>“${h(e.better)}”</p></div></div><p class="question-plan"><strong>Planned support:</strong> ${h(e.support)}</p><p class="question-basis">${h(e.basis)}</p></div></details>`).join('')}</div><details class="stage-value-map"><summary>Why every stage matters—and where each plan helps</summary><p>Planned support mapped to the free nine-stage overview. These are workflow aids for a competent Committee, not automatic legal compliance.</p><ol>${stages.map(([n,title,risk,value])=>`<li><span>${n}</span><div><h3>${h(title)}</h3><p>${h(risk)}</p><p><strong>${h(value)}</strong></p></div></li>`).join('')}</ol></details><div class="provider-next"><p>The competent IC/LC must verify each proposed question and draft. Software does not decide relevance, credibility, guilt or an appeal.</p><a class="btn btn-dark" href="#enquire?plan=professional">Walk me through questions &amp; reporting →</a></div></div></section>`;}
function providerConfidence(){return `<section class="section provider-confidence" aria-labelledby="provider-confidence-title"><div class="wrap"><div class="home-section-heading"><div><span class="eyebrow dark">BEFORE YOU COMMIT TO ANY PROVIDER</span><h2 id="provider-confidence-title">Buy a clear scope.<br/>Ask to see the work.</h2></div><p>A training credential or a large quote does not tell you exactly what inquiry support you will receive. Ask every provider—including us—to demonstrate the process and put the deliverables in writing.</p></div><div class="provider-checks"><article><span>01 / COMPETENCE</span><h3>Who does the work?</h3><p>Check relevant inquiry experience, applicable service-rule knowledge, named responsibilities and conflict checks. Ask who reviews the output and what support actually includes.</p></article><article><span>02 / FAIRNESS</span><h3>How are both sides heard?</h3><p>Look for neutral questioning, consideration of contrary material, participation records and reasons for findings. Avoid promises of a predetermined result.</p></article><article><span>03 / VALUE</span><h3>What does the quote cover?</h3><p>Compare the same deliverables: hearings, records, report drafting, reviews, external-member or legal services, taxes and exclusions. Our listed plan prices cover the stated planned software scope; they are not an all-inclusive professional-services fee.</p></article></div><div class="provider-next"><p><strong>Keep ownership of the decision.</strong> Tools support a competent Committee; they do not replace required members, independent judgment, training or legal advice.</p><a href="#enquire?plan=professional" class="btn btn-dark">Show me the planned workflow →</a></div></div></section>`;}
function buyerQuestions(){return `<section class="section buyer-questions"><div class="wrap"><div class="home-section-heading"><div><span class="eyebrow dark">BEFORE YOU CHOOSE</span><h2>Clear answers.<br/>A considered next step.</h2></div><p>Understand what you can use today and what to discuss before choosing a professional plan.</p></div><div class="buyer-faq-grid"><details><summary>What can I use right now?</summary><p>Free individual guidance, editable drafts, all nine inquiry stages, searchable FAQs and the judgment library. Paid workspaces and knowledge products are planned.</p></details><details><summary>Which plan adds the full report builder?</summary><p>Essential includes a basic findings/report template. Professional adds evidence-linked question planning, the current case-adaptive inquiry-report builder and readiness checks. Advanced adds adaptive and complex-proceeding tools.</p></details><details><summary>Will a plan prevent an appeal or guarantee satisfaction?</summary><p>No. Appeal rights remain available, and either party may disagree with the outcome. The intended value is a fairer, more transparent working process: documented opportunities to participate, neutral examination and reasons that can be reviewed. No appeal-success or satisfaction rate is claimed.</p></details><details><summary>Does the software make the Committee’s decisions?</summary><p>No. The Committee evaluates the material, records its reasoning and approves its work. A software account does not replace a Committee member or the required participation.</p></details><details><summary>What happens after I submit a request?</summary><p>Submit your requirements on this website. After a successful save, you receive a reference on screen. The team reviews the request and contacts you about availability and scope. No payment, appointment or plan activation is created by submitting.</p></details></div>${institutionalSectionCTA('Have the answers you need?','Take the next step with a walkthrough of the relevant plan and its written scope.')}<div class="publisher-panel"><div><span class="eyebrow dark">THE COSMIC ENERGIZERS</span><h3>Know the source. Know who to contact.</h3><p>Inspect the statutory links, complete FAQ answers and judgment references. Contact the team for product scope and demonstration enquiries.</p><a class="text-link" href="#faq">Explore the source-linked knowledge centre →</a></div><div><a href="tel:+917902171932">+91 79021 71932</a><a href="mailto:trainings@thecosmicenergizers.com">trainings@thecosmicenergizers.com</a><a href="mailto:ankur.attorneyatlaw@gmail.com">ankur.attorneyatlaw@gmail.com</a><span>Independent public preview · Professional services planned</span></div></div></div></section>`;}
function enquiryPage(){const ids=['essential','professional','advanced','institutional','enterprise','knowledge'],chosen=new URLSearchParams(location.hash.split('?')[1]||location.search).get('plan'),plan=ids.includes(chosen)?chosen:'unsure';document.body.dataset.page='enquire';document.title='Request a demonstration | The Cosmic Energizers';app.innerHTML=header('See the support behind a better-prepared inquiry.','Review the working procedural guide and discuss any proposed additions. Confirm deliverables, fees and access before committing; no payment is required for this request.','REQUEST A DEMONSTRATION')+`<div class="app-bg"><div class="wrap workspace enquiry-layout"><section class="enquiry-card"><h2>Tell us what you need.</h2><p>Use business requirements only. Do not submit complaint narratives, party names, witness details or evidence.</p><form id="demonstration-brief"><label><span>Your name<span class="required-mark" aria-hidden="true">&nbsp;*</span></span><input name="contact_name" required maxlength="80" autocomplete="name" placeholder="Your preferred name"></label><label><span>Contact email<span class="required-mark" aria-hidden="true">&nbsp;*</span></span><input name="email" required type="email" maxlength="254" autocomplete="email" placeholder="you@organisation.com"></label><label><span>Organisation<span class="required-mark" aria-hidden="true">&nbsp;*</span></span><input name="organisation" required maxlength="100" autocomplete="organization" placeholder="Organisation or team name"></label><label><span>Your role<span class="required-mark" aria-hidden="true">&nbsp;*</span></span><select name="role" required><option>IC / LC member</option><option>Presiding Officer / Chairperson</option><option>HR / employer representative</option><option>External Member / adviser</option><option>Other organisational role</option></select></label><label><span>Primary interest<span class="required-mark" aria-hidden="true">&nbsp;*</span></span><select name="plan" required>${[['unsure','Help choosing a plan'],['essential','Inquiry Essential'],['professional','Inquiry Professional'],['advanced','Inquiry Advanced'],['institutional','Institutional Plus'],['enterprise','Government / Enterprise'],['knowledge','Readiness Toolkit / Expert Knowledge']].map(([id,name])=>`<option value="${id}" ${plan===id?'selected':''}>${name}</option>`).join('')}</select></label><label><span>Support needed<span class="required-mark" aria-hidden="true">&nbsp;*</span></span><select name="need" required><option>Core inquiry workflow and record organisation</option><option>Evidence-linked questions and report drafting</option><option>Complex proceedings and adaptive tools</option><option>Organisation-specific configuration and onboarding</option><option>Readiness and professional knowledge resources</option></select></label><label><span>Expected application users<span class="required-mark" aria-hidden="true">&nbsp;*</span></span><select name="users" required><option>Not yet decided</option><option>Up to 2</option><option>Up to 5</option><option>Up to 8</option><option>Up to 15</option><option>Contractual team size</option></select></label><label class="enquiry-trap" hidden aria-hidden="true">Leave blank<input name="website" tabindex="-1" autocomplete="off"></label><label class="enquiry-consent"><input name="consent" type="checkbox" required><span>I agree that The Cosmic Energizers may store these details privately and contact me about this request.<span class="required-mark" aria-hidden="true">&nbsp;*</span></span></label><button class="btn btn-dark" type="submit" disabled>Request my demonstration →</button><p id="enquiry-submit-status" role="status">Checking request availability…</p><p class="enquiry-local-note">Details are used to review and respond to your enquiry. They are not published or added to the community. No marketing subscription is created. Contact training@thecosmicenergizers.com for review or removal requests.</p></form></section><aside class="enquiry-review"><span class="eyebrow dark">WHAT HAPPENS NEXT</span><h2>One request.<br/>A clear next step.</h2><ol><li>Submit your requirements on this website.</li><li>Receive an on-screen reference after your request is saved.</li><li>The team reviews your requirements and contacts you about availability and scope.</li></ol><div id="enquiry-ready" hidden><h3 id="enquiry-confirmation-title" tabindex="-1">Your request has been received.</h3><p class="enquiry-status" role="status">Saved privately for the team to review.</p><p class="enquiry-reference">Reference: <strong id="enquiry-receipt"></strong></p><pre id="enquiry-brief-text"></pre><div class="enquiry-actions"><button type="button" class="btn btn-light" id="enquiry-download">Download my receipt</button><a class="btn btn-dark" href="#product-preview">Explore the workspace preview →</a></div><p>This request is not a purchase, confirmed appointment or paid-plan activation.</p></div><div class="enquiry-contact"><strong>Need more context before choosing?</strong><a href="mailto:training@thecosmicenergizers.com?subject=Navigator%20organisation%20walkthrough">Email the team about a walkthrough</a><a href="tel:+917902171932">Call +91 79021 71932</a><a href="#pricing">Compare the plans →</a><a href="#product-preview">Preview the working guide →</a></div></aside></div></div>`;const form=document.getElementById('demonstration-brief'),submit=form.querySelector('[type="submit"]'),status=document.getElementById('enquiry-submit-status');let ready=false,busy=false;
 fetch('/api/enquiries/config',{signal:AbortSignal.timeout(8000)}).then(r=>r.ok?r.json():Promise.reject()).then(data=>{if(!form.isConnected)return;ready=data.enabled===true;submit.disabled=!ready;status.textContent=ready?'Ready to submit securely on this website.':'Online requests are temporarily unavailable. Use the email or phone contact beside this form.';}).catch(()=>{if(form.isConnected)status.textContent='Online requests are temporarily unavailable. Use the email or phone contact beside this form.';});
 form.addEventListener('submit',async event=>{event.preventDefault();if(!ready||busy)return;busy=true;submit.disabled=true;submit.textContent='Submitting…';form.setAttribute('aria-busy','true');status.textContent='Saving your request…';const data=new FormData(form),payload=Object.fromEntries(['contact_name','email','organisation','role','plan','need','users','website'].map(k=>[k,String(data.get(k)||'')]));payload.consent=data.get('consent')==='on';try{const r=await fetch('/api/enquiries',{method:'POST',signal:AbortSignal.timeout(20000),headers:{'Content-Type':'application/json',...(window.NavigatorAnalytics?.enquiryHeaders()||{})},body:JSON.stringify(payload)} );let result;try{result=await r.json()}catch{throw Error('We could not confirm your request. Your details remain in the form; please check with the team before repeating a submission.')}if(!r.ok)throw Error(result.error||'Request could not be confirmed. Please try again.');if(result.status!=='received'||!/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(result.receipt))throw Error('Request could not be confirmed. Please try again.');if(!form.isConnected)return;document.getElementById('enquiry-receipt').textContent=result.receipt;const option=form.elements.plan.selectedOptions[0].textContent;document.getElementById('enquiry-brief-text').textContent=['POSH Legal Navigator — request receipt','Reference: '+result.receipt,'Plan interest: '+option,'Name: '+payload.contact_name,'Organisation: '+payload.organisation,'Support needed: '+payload.need,'Application users: '+payload.users,'','Received for private review. No payment or plan activation.'].join('\n');document.getElementById('enquiry-ready').hidden=false;status.textContent='Request received. Save the reference shown beside the form.';submit.textContent='Request received ✓';ready=false;form.querySelectorAll('input,select').forEach(x=>x.disabled=true);document.getElementById('enquiry-confirmation-title').focus({preventScroll:true});document.getElementById('enquiry-ready').scrollIntoView({block:'nearest',behavior:'smooth'});}catch(e){if(form.isConnected){status.textContent=['TimeoutError','AbortError','TypeError'].includes(e.name)?'We could not confirm whether your request arrived. Your details remain here. Contact the team before sending again.':e.message||'We could not confirm your request. Contact the team before sending again.';submit.disabled=false;submit.textContent='Retry after checking with the team →';}}finally{busy=false;form.removeAttribute('aria-busy');}});document.getElementById('enquiry-download').addEventListener('click',()=>{const text=document.getElementById('enquiry-brief-text').textContent;if(!text)return;const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='POSH-enquiry-receipt.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});}
document.addEventListener('click',event=>{const tab=event.target.closest('[data-concept-tab]');if(!tab)return;const root=tab.closest('.product-concept');root.querySelectorAll('[data-concept-tab]').forEach(button=>{const active=button===tab;button.setAttribute('aria-selected',String(active));button.tabIndex=active?0:-1;document.getElementById('concept-'+button.dataset.conceptTab).hidden=!active;});});
document.addEventListener('keydown',event=>{const tab=event.target.closest('[data-concept-tab]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const tabs=[...tab.closest('.concept-tabs').querySelectorAll('[data-concept-tab]')],i=tabs.indexOf(tab),next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(i+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[next].click();tabs[next].focus();});

