function founderProfile(){return `<section class="sales-section founder-profile" id="founder" aria-labelledby="founder-title"><div class="sales-wrap"><div class="founder-layout"><div class="founder-identity"><p class="sales-kicker">THE PROFESSIONAL BEHIND NAVIGATOR</p><h2 id="founder-title">Ankur Agrawal (LLB)</h2><p class="founder-role">Founder, The Cosmic Energizers<br>POSH trainer &amp; consultant</p><div class="founder-credentials"><span>POSH training</span><span>Internal Committee training</span><span>HR experience</span></div><a class="btn btn-dark" href="mailto:training@thecosmicenergizers.com?subject=Navigator%20professional%20profile%20and%20walkthrough">Request profile &amp; walkthrough</a></div><div class="founder-story"><h3>Know the person. Understand the approach.</h3><p>Ankur’s background includes POSH training and consulting, experience in HR, multiple POSH certifications from government institutions, and training for Internal Committees.</p><p>This experience informs Navigator’s focus on practical preparation: relevant questions, fair participation, clear procedural records and independent Committee decisions.</p></div></div><div class="founder-values founder-values-grid"><article><h4>Professional accountability</h4><p>Ask about relevant experience and qualifications before agreeing the engagement. Discuss your organisation’s requirements directly with the team.</p></article><article><h4>Clear scope before payment</h4><p>Review the working guide, confirm what is included today and obtain the fee, validity, users and support scope in writing.</p></article><article><h4>Your Committee stays independent</h4><p>Professional credentials do not imply government approval of this software. Navigator does not decide findings or guarantee an appeal outcome.</p></article></div></div></section>`;}

function institutionalOutcomes(){return `<section class="section institutional-outcomes" aria-labelledby="outcomes-title"><div class="wrap"><div class="home-section-heading"><div><span class="eyebrow dark">FROM COMPLAINT TO A REASONED REPORT</span><h2 id="outcomes-title">Give every stage<br/>a clear working record.</h2></div><p>For IC members, Presiding Officers, external members and HR teams supporting a POSH inquiry in India. Choose the depth of tools your proceeding needs; core procedural safeguards belong in every plan.</p></div><div class="home-value-grid"><article><span class="home-value-number">01 / ORGANISE</span><h3>Know what needs attention.</h3><p>Bring notices, replies, hearing dates, attendance and evidence references into one planned workflow, with a basic report template in Essential.</p></article><article><span class="home-value-number">02 / EXAMINE</span><h3>Hear both sides. Test the material.</h3><p>Professional adds allegation-specific question planning and a full matrix of supporting and contrary material for Committee review.</p></article><article><span class="home-value-number">03 / EXPLAIN</span><h3>Make the reasons traceable.</h3><p>Professional adds the current case-adaptive inquiry-report builder and eight legal release gates. Advanced adds adaptive tools for complex proceedings.</p></article></div><div class="institutional-urgency"><strong>Build the record while the inquiry happens.</strong><p>Preparation before the next hearing is more useful than reconstructing missing steps after a challenge. Appeal rights remain available; no plan promises an appeal-proof result.</p></div>${institutionalSectionCTA('See which tools fit your proceeding.','Review the planned scope before choosing a plan. No confidential case details are needed.')}</div></section>`;}
