function currentStageIndex(role){return E.stages[role].findIndex(x=>x.id===pos[role]);}
function control(q,ans){
 if(q.kind==='date')return `<input class="date-input" aria-label="${h(q.label)}" data-answer="${h(q.id)}" type="date" value="${h(ans||'')}" max="${E.indiaDay()}" />`;
 if(q.kind==='multi')return `<div class="options options-multi" role="group" aria-label="${h(q.label)}">${q.choices.map(o=>`<button type="button" class="option ${Array.isArray(ans)&&ans.includes(o.value)?'selected':''}" data-answer="${h(q.id)}" data-value="${h(o.value)}" data-multi="true" aria-pressed="${Array.isArray(ans)&&ans.includes(o.value)?'true':'false'}"><span class="check-square" aria-hidden="true">${Array.isArray(ans)&&ans.includes(o.value)?'✓':''}</span><span>${h(o.label)}${o.detail?`<small>${h(o.detail)}</small>`:''}</span></button>`).join('')}</div>`;
 return `<div class="options" role="group" aria-label="${h(q.label)}">${q.choices.map(o=>`<button type="button" class="option ${o.value===ans?'selected':''}" data-answer="${h(q.id)}" data-value="${h(o.value)}" aria-pressed="${o.value===ans?'true':'false'}"><span class="radio-circle" aria-hidden="true"></span><span>${h(o.label)}${o.detail?`<small>${h(o.detail)}</small>`:''}</span></button>`).join('')}</div>`;
}
function alerts(role,state){
 if(role!=='woman')return '';
 let out='';
 if(state['w.urgent']==='yes')out+=`<div class="notice urgent"><strong>Immediate safety comes first.</strong> If there is present danger, contact local emergency services or police. No authority has been contacted by this application.</div>`;
 if(state['w.age']==='minor'&&['yes','unsure'].includes(state['w.childIndicators']))out+=`<div class="notice urgent"><strong>Child-protection screening:</strong> Where a POCSO offence is known or reasonably apprehended, Section 19 provides for reporting to the Special Juvenile Police Unit or local police. This screen does not establish that an offence occurred.</div>`;
 if(state['w.concern']==='other'||state['w.conduct']==='nonsexual')out+=`<div class="notice warning">The current answers do not indicate sexual conduct. The next steps will focus on other appropriate workplace grievance routes, not automatically generate a POSH complaint.</div>`;
 if(state['w.workforce']==='10plus'&&state['w.againstEmployer']!=='yes'&&state['w.ic']==='no')out+=`<div class="notice warning"><strong>IC not constituted despite 10+ workers:</strong> Request the written IC constitution order and urgent action; contact the District Officer for proper forum guidance. Do not assume automatic LC jurisdiction or delay a time-sensitive complaint.</div>`;
 if(state['w.workforce']==='10plus'&&state['w.againstEmployer']!=='yes'&&state['w.ic']==='unknown')out+=`<div class="notice warning"><strong>IC information unavailable:</strong> Ask for the latest signed IC order and secure receiving contact. Do not treat missing information as proof that no IC exists.</div>`;
 if(state['w.conciliation']==='yes'&&state['w.conciliationVoluntary']==='no')out+=`<div class="notice urgent"><strong>Conciliation must be voluntary.</strong> No unconditional Section 10 request will be generated when pressure is indicated.</div>`;
 return out;
}
function wizard(role){
 const state=states[role],stage=pos[role],isWoman=role==='woman';
 if(stage==='result')return results(role);
 const stages=E.stages[role],i=currentStageIndex(role),qs=E.activeQuestions(role,state,stage);
 const complete=E.stageReady(role,state,stage);
 const title={start:isWoman?'Tell us the broad concern':'Start with the procedural position',safety:'Safety and safeguarding',conduct:'Understand the kind of conduct',workplace:'Establish the workplace connection',timeline:'Understand the relevant timeline',forum:'Identify the appropriate forum',next:'Choose your next step',notice:'Review the notice and materials',preparation:'Prepare a fair, factual response'}[stage]||stage;
 const guidance=window.NavigatorGuidanceContext.forStage(role,stage);
 const desc=isWoman?'Answer without disclosing names, witness identities or private incident narratives.':'Identify the actual documents and procedural status; avoid assumptions about the outcome.';
 app.innerHTML=header(isWoman?'Guidance for an aggrieved woman':'Guidance for a respondent',isWoman?'Free and privacy-conscious procedural guidance.':'Free, neutral guidance on procedural rights and lawful preparation.',isWoman?'PUBLIC GUIDANCE · NO ACCOUNT':'PUBLIC GUIDANCE · NO ACCOUNT')+`<div class="app-bg"><div class="wrap workspace"><div class="wizard-layout"><section class="wizard-card"><div class="step-label"><span>${h(stages[i].name)}</span><span>STAGE ${i+1} OF ${stages.length}</span></div><div class="step-meter" aria-hidden="true">${stages.map((x,j)=>`<span class="${j<=i?'done':''}"></span>`).join('')}</div><h2 class="stage-title">${h(title)}</h2><p class="stage-desc">${h(desc)}</p>${qs.map(q=>`<div class="question"><h3>${h(q.label)}</h3>${q.hint?`<p class="question-hint">${h(q.hint)}</p>`:''}${control(q,state[q.id])}${q.kind==='date'&&state[q.id]&&!E.validAnswer(q,state[q.id])?'<p class="notice warning">Enter a valid date that is not in the future.</p>':''}</div>`).join('')}${alerts(role,state)}<div class="stage-actions"><button class="btn btn-light" data-nav="back" ${i===0?'disabled':''}>← Back</button><button class="btn btn-dark" data-nav="continue" ${complete?'':'disabled'}>${i===stages.length-1?'View my action plan':'Continue'} →</button></div><p class="privacy-line">No names or confidential case files are requested. Selected answers remain in this page until you reload or reset.</p></section><aside class="aside-card step-guidance" aria-labelledby="step-guidance-title"><h3 id="step-guidance-title">${h(guidance.title)}</h3><p class="section-reference">${h(guidance.sections)}</p><h4>What this means here</h4><p>${h(guidance.meaning)}</p><h4>Your next step</h4><p>${h(guidance.next)}</p><details><summary>Sources and limits</summary><p>${h(guidance.limit)}</p><a class="info-link" target="_blank" rel="noopener noreferrer" href="${h(E.SOURCES.act.uri)}">Read the POSH Act ↗</a><br><a class="info-link" target="_blank" rel="noopener noreferrer" href="${h(E.SOURCES.rules.uri)}">Read the Central Rules ↗</a></details></aside></div></div></div>`;
}
function results(role){
 const isWoman=role==='woman',result=E.outcome(role,states[role]);
 const acts=showAll?result.actions:result.actions.slice(0,5);
 app.innerHTML=header('Your tailored next steps','Based on the active answers in this session. This is guidance, not a legal determination.','ROLE-SPECIFIC ACTION PLAN')+`<div class="app-bg"><div class="wrap workspace"><div class="wizard-layout"><section class="result-card"><div class="result-header"><div><span class="eyebrow dark">YOUR ACTION PLAN</span><h2>What you should do next — based on your answers</h2><p>${result.actions.length} specific step${result.actions.length===1?'':'s'} identified from the information you selected. Prioritised actions appear first; expand to see the rest.</p></div><span class="status-pill">Preliminary guidance</span></div>${alerts(role,result.s)}<details class="answer-review"><summary>Review the answers used in this plan</summary><dl>${result.answers.map(x=>`<div><dt>${h(x.question)}</dt><dd>${h(x.answer)}</dd></div>`).join('')}</dl><p>Only answers relevant to the active route are used. Edit responses to correct anything.</p></details><div class="action-list">${acts.map((a,i)=>`<article class="action-item"><span class="action-index">${String(i+1).padStart(2,'0')}</span><div><h3>${h(a.title)}</h3><p>${h(a.detail)}</p><div class="action-instructions">${a.now?`<p><strong>Do now</strong><span>${h(a.now)}</span></p>`:''}${a.records?`<p><strong>Records to keep</strong><span>${h(a.records)}</span></p>`:''}${a.next?`<p><strong>What follows</strong><span>${h(a.next)}</span></p>`:''}</div><span class="source">${h(a.source)} · Responsible: ${h(a.owner)}</span></div></article>`).join('')}</div>${!showAll&&result.actions.length>5?`<button class="btn btn-light" style="margin-top:16px" data-nav="more">View ${result.actions.length-5} more action(s) ↓</button>`:''}<div class="divider"></div><h3>Prepare your editable Word document</h3><p class="stage-desc">The document is generated locally in your browser. It carries over relevant answers already supplied, clearly labelled as your selections, and leaves only unprovided particulars as editable placeholders. It never invents testimony. It is not a filed or served document.</p><div class="result-tools">${isWoman?(result.eligibleDoc?`<button class="btn btn-dark" data-download="woman">Download complaint DOCX ↓</button>`:`<span class="notice warning">A POSH complaint draft is not provided for the currently non-sexual route.</span>`):`<button class="btn btn-dark" data-download="respondent">Download written-reply DOCX ↓</button>`}${isWoman&&result.eligibleDoc&&D.canConciliate(result.s)?`<button class="btn btn-light" data-download="conciliation">Download separate Section 10 request DOCX ↓</button>`:''}<button class="btn btn-light" data-nav="back">← Edit responses</button><button class="btn btn-light" data-nav="reset">Start over</button></div></section><aside class="aside-card"><h3>Read this before proceeding</h3>${result.notices.map(n=>`<p class="aside-mini">${h(n)}</p>`).join('')}<hr/><p class="aside-mini">Dates, forum competence, service-rule applicability and statutory exceptions must be reviewed with the competent authority or a qualified professional. This software has taken no external action.</p><a href="#home" class="info-link">Return to homepage ↗</a></aside></div></div></div>`;
}
function demoPage(){
 app.innerHTML=header('Inquiry lifecycle — stages, timelines and sections','A simple statutory overview, including witness examination and appreciation of evidence. No casework, hearing records or reports are available in the free demo.','FREE INQUIRY OVERVIEW')+`<div class="app-bg inquiry-bg"><div class="wrap workspace inquiry-workspace"><section class="demo-overview" aria-labelledby="demo-title"><div class="demo-overview-head"><div><span class="eyebrow dark">EDUCATIONAL OVERVIEW · NO CASE ACCESS</span><h2 id="demo-title">Inquiry stages and key time limits.</h2><p>Broad stages, principal provisions and indicative deadlines. Hover, focus or tap an underlined section or rule to read its meaning. Conciliation is conditional; applicable rules can vary.</p></div><span class="status-pill">Free overview</span></div><div class="overview-brand"><strong>The Cosmic Energizers</strong><span>POSH Legal Navigator · Independent educational overview</span><a href="tel:+917902171932">+91 79021 71932</a><a href="mailto:ankur.attorneyatlaw@gmail.com">ankur.<wbr>attorneyatlaw<wbr>@gmail.com</a></div><div class="inquiry-view-controls"><div role="group" aria-label="Inquiry reading view"><button class="btn btn-dark" type="button" data-inquiry-view="all" aria-pressed="true">All nine stages</button><button class="btn btn-light" type="button" data-inquiry-view="focus" aria-pressed="false">One stage at a time</button></div><p>All nine stages are free. Choose the view that is easiest to read.</p></div><nav class="inquiry-stage-nav" aria-label="Choose an inquiry stage" hidden>${overviewStages.map((stage,i)=>`<button type="button" data-inquiry-stage="${i}" aria-current="${i===0?'step':'false'}"><span>${String(i+1).padStart(2,'0')}</span>${h(stage.title)}</button>`).join('')}</nav><div class="inquiry-stage-content"><ol class="timeline-basic">${overviewStages.map((stage,i)=>`<li><span class="timeline-num">${String(i+1).padStart(2,'0')}</span><div class="timeline-copy"><h3 class="timeline-title" tabindex="-1">${h(stage.title)}</h3><span class="timeline-law">${window.NavigatorLegal.referenceHTML(stage.section)}</span><span class="timeline-brand"><span class="timeline-brand-name">The Cosmic Energizers</span><span class="timeline-contact"><a class="timeline-phone" href="tel:+917902171932">+91 79021 71932</a><span class="contact-separator" aria-hidden="true"> · </span><a href="mailto:ankur.attorneyatlaw@gmail.com">ankur.<wbr>attorneyatlaw<wbr>@gmail.com</a></span></span><span class="timeline-time"><span aria-hidden="true">◷</span> ${window.NavigatorLegal.referenceHTML(stage.time)}</span><details class="stage-example"><summary>Simple fictional example</summary><p>${h(stageExamples[i])}</p><small>Illustration only · Read with the provisions above.</small></details>${stage.guidance?`<div class="stage-guidance">${stage.guidance.map(note=>`<p><strong>${h(note.title)}</strong>${h(note.text)}</p>`).join('')}<a class="stage-source" href="${h(E.SOURCES.act.uri)}" target="_blank" rel="noopener noreferrer">Read Section 10 ↗</a></div>`:''}</div></li>`).join('')}</ol><div class="inquiry-pagination" hidden><button type="button" class="btn btn-light" data-inquiry-step="-1">← Previous</button><span class="inquiry-position" role="status" aria-live="polite">Stage 1 of 9</span><button type="button" class="btn btn-dark" data-inquiry-step="1">Next stage →</button></div></div><aside class="demo-safety"><strong>Throughout the process</strong><p>Keep complaint and inquiry information confidential (Section 16). Protect parties, witnesses, Committee and external members from threats, victimisation and interference. Report safety concerns through an appropriate independent channel. Fair safeguards do not presume guilt. <a href="#faq/retaliation-all-stakeholders">Safety guidance →</a></p></aside><details class="inquiry-essential-details"><summary>Read more: safeguards and legal routes</summary><p><strong>Protection:</strong> Section 19(a) addresses a safe working environment. Section 12 interim relief specifically concerns the aggrieved woman’s written request; remedies are not identical for every stakeholder.</p><p><strong>Applicable procedure:</strong> Check Central Rule 7 and service/sector rules for applicability. The seven-working-day rule concerns forwarding the complaint copy, not acceptance or rejection. The Committee evaluates witnesses, evidence and findings.</p><p><strong>Separate routes:</strong> A POSH inquiry is not a criminal trial. Police referrals depend on the applicable law; the LC does not hear appeals against an IC. <a href="#faq/when-police-referral">Police / BNS FAQ</a> · <a href="#faq/appeal-ic-to-lc">Appeal FAQ</a></p></details><div class="overview-brand"><strong>The Cosmic Energizers</strong><span>POSH Legal Navigator · Independent educational overview</span><a href="tel:+917902171932">+91 79021 71932</a><a href="mailto:ankur.attorneyatlaw@gmail.com">ankur.<wbr>attorneyatlaw<wbr>@gmail.com</a></div><div class="demo-actions"><a class="btn btn-dark" href="#enquire">Enquire about professional access ↗</a><a class="btn btn-light" href="#journeys">Explore free personal guidance</a></div></section></div></div>`;
}

function navigate(){let path=routeName();if(path==='integrity'){location.replace('/privacy.html');return;}const business=['institutional','pricing','institutional/plans','plan-comparison','product-preview','enquire'].includes(path)||path.startsWith('plan-');const cta=document.querySelector('.nav-cta');if(cta){cta.href='/account';cta.textContent='Sign in';}document.body.dataset.page=path.split('/')[0];document.title=({woman:'Aggrieved Woman Guidance',respondent:'Respondent Guidance',demo:'Inquiry Stages and Timelines',community:'Community',faq:'POSH Knowledge Library'}[path]||'POSH Legal Navigator')+' | The Cosmic Energizers';if(path==='faq'||path.startsWith('faq/')){window.NavigatorFAQ.render(app,path);scrollTo(0,0)}else if(path==='community'||path.startsWith('community/')){window.NavigatorCommunity.render(app,path);scrollTo(0,0)}else if(path==='guidance'||path==='journeys'){freeGuidancePage();scrollTo(0,0)}else if(path==='enquire'){enquiryPage();scrollTo(0,0)}else if(['woman','respondent'].includes(path)){wizard(path);scrollTo(0,0)}else if(path==='demo'){demoPage();scrollTo(0,0)}else if(path==='institutional'||path==='pricing'||path==='institutional/plans'||path==='plan-comparison'||path.startsWith('plan-')){institutionalPage();scrollTo(0,0);if(!['institutional','pricing','institutional/plans'].includes(path))setTimeout(()=>document.getElementById(path==='institutional/plans'?'pricing':path)?.scrollIntoView({block:'start',behavior:'smooth'}),20);}else{home();if(path!=='home'){setTimeout(()=>document.getElementById(path)?.scrollIntoView({block:'start',behavior:'smooth'}),20);}else scrollTo(0,0)}}
window.addEventListener('hashchange',()=>{navigate();window.dispatchEvent(new Event('navigator:route')); if(!routeName().startsWith('faq/')){const target=document.getElementById(routeName())||app.querySelector('h1');if(target){target.tabIndex=-1;target.focus({preventScroll:true});}}});
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();const main=document.getElementById('main');main.tabIndex=-1;main.focus();});
document.addEventListener('click',e=>{if(e.target.closest('.mobile-menu a'))document.querySelector('.mobile-menu')?.removeAttribute('open');});
document.addEventListener('keydown',e=>{const menu=document.querySelector('.mobile-menu[open]');if(e.key==='Escape'&&menu){menu.removeAttribute('open');menu.querySelector('summary').focus();}});
document.addEventListener('click',e=>{
 const t=e.target.closest('button');if(!t)return;
 if(t.dataset.answer&&t.dataset.value!==undefined){const role=routeName();if(!states[role])return;const id=t.dataset.answer,v=t.dataset.value;
 if(t.dataset.multi==='true') {let arr=Array.isArray(states[role][id])?[...states[role][id]]:[];if(['none','unsure'].includes(v))arr=arr.includes(v)?[]:[v];else{arr=arr.filter(x=>!['none','unsure'].includes(x));arr=arr.includes(v)?arr.filter(x=>x!==v):[...arr,v];}states[role][id]=arr;}
 else states[role][id]=v;
 wizard(role);Array.from(app.querySelectorAll('[data-answer]')).find(el=>el.dataset.answer===id&&el.dataset.value===v)?.focus({preventScroll:true});return;}
 if(t.dataset.nav){const role=routeName();if(!states[role])return;const n=t.dataset.nav;if(n==='continue'){const s=pos[role],qs=E.activeQuestions(role,states[role],s);if(E.stageReady(role,states[role],s)){pos[role]=E.nextStage(role,states[role],s);wizard(role);} }if(n==='back'){pos[role]=E.previousStage(role,states[role],pos[role]);wizard(role);}if(n==='more'){showAll=true;wizard(role);}if(n==='reset'){states[role]={};pos[role]='start';showAll=false;wizard(role);}const heading=app.querySelector('.stage-title, .result-card h2');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}scrollTo(0,0);return;}
 if(t.dataset.download){let bytes,name;const type=t.dataset.download;if(type==='woman'){if(!E.outcome('woman',states.woman).eligibleDoc)return;bytes=D.womanComplaint(E.activeAnswers('woman',states.woman));name='POSH_Complaint_Editable_Draft.docx';}else if(type==='conciliation'){const answers=E.activeAnswers('woman',states.woman);if(!D.canConciliate(answers))return;bytes=D.womanConciliation(answers);name='POSH_Section10_Voluntary_Conciliation_Request.docx';}else if(type==='respondent'){bytes=D.respondentReply(E.activeAnswers('respondent',states.respondent));name='POSH_Respondent_Reply_Editable_Draft.docx';}else{return;}D.download(name,bytes);return;}
});
document.addEventListener('change',e=>{const t=e.target;if(t.matches('input[data-answer]')){const role=routeName();if(!states[role])return;const answerId=t.dataset.answer;states[role][answerId]=t.value;wizard(role);Array.from(app.querySelectorAll('input[data-answer]')).find(el=>el.dataset.answer===answerId)?.focus({preventScroll:true})}});
// The focused reading view reuses the same free, legally reviewed stage content.
let focusedStage=0;
function updateInquiryView(mode,moveFocus=false){
 const panel=document.querySelector('.demo-overview');if(!panel)return;
 const focused=mode==='focus';panel.classList.toggle('focused',focused);
 panel.querySelector('.inquiry-stage-nav').hidden=!focused;
 panel.querySelector('.inquiry-pagination').hidden=!focused;
 panel.querySelectorAll('[data-inquiry-view]').forEach(b=>{const active=b.dataset.inquiryView===mode;b.setAttribute('aria-pressed',String(active));b.classList.toggle('btn-dark',active);b.classList.toggle('btn-light',!active)});
 const cards=panel.querySelectorAll('.timeline-basic>li');cards.forEach((card,i)=>card.hidden=focused&&i!==focusedStage);
 panel.querySelectorAll('[data-inquiry-stage]').forEach((b,i)=>b.setAttribute('aria-current',i===focusedStage?'step':'false'));
 panel.querySelector('.inquiry-position').textContent='Stage '+(focusedStage+1)+' of '+cards.length;
 panel.querySelector('[data-inquiry-step="-1"]').disabled=focusedStage===0;
 panel.querySelector('[data-inquiry-step="1"]').disabled=focusedStage===cards.length-1;
 if(focused&&moveFocus)cards[focusedStage].querySelector('h3').focus({preventScroll:true});
}
document.addEventListener('click',e=>{
 const view=e.target.closest('[data-inquiry-view]');if(view){focusedStage=0;updateInquiryView(view.dataset.inquiryView);return;}
 const stage=e.target.closest('[data-inquiry-stage]'),step=e.target.closest('[data-inquiry-step]');
 if(stage||step){focusedStage=stage?Number(stage.dataset.inquiryStage):Math.max(0,Math.min(8,focusedStage+Number(step.dataset.inquiryStep)));updateInquiryView('focus',true);}
});
